```rust
#[derive(Debug, PartialEq, Clone)]
pub enum Expr {
    Literal(Literal),
    Identifier(String),
    BinaryOp {
        left: Box<Expr>,
        op: String,
        right: Box<Expr>,
    },
    UnaryOp {
        op: String,
        operand: Box<Expr>,
    },
    FunctionCall {
        function: Box<Expr>,
        arguments: Vec<Expr>,
    },
    ListComprehension {
        expr: Box<Expr>,
        variable: String,
        iter: Box<Expr>,
        condition: Option<Box<Expr>>,
    },
}

#[derive(Debug, PartialEq, Clone)]
pub enum Literal {
    Number(f64),
    String(String),
    Boolean(bool),
}

#[derive(Debug, PartialEq, Clone)]
pub enum Stmt {
    VariableDeclaration {
        name: String,
        value: Option<Expr>,
    },
    Assignment {
        name: String,
        value: Expr,
    },
    If {
        condition: Expr,
        then_block: Vec<Stmt>,
        else_block: Option<Vec<Stmt>>,
    },
    While {
        condition: Expr,
        block: Vec<Stmt>,
    },
    For {
        variable: String,
        iter: Expr,
        block: Vec<Stmt>,
    },
    FunctionDefinition {
        name: String,
        parameters: Vec<String>,
        body: Vec<Stmt>,
    },
    ClassDefinition {
        name: String,
        methods: Vec<Stmt>,
    },
    Import {
        module: String,
    },
    Return(Option<Expr>),
    Expr(Expr),
}

pub type Program = Vec<Stmt>;
```
