  rule(:space?) { space.maybe }
  rule(:digit)  { match('[0-9]') }
  rule(:digits) { digit.repeat(1) }
  rule(:lparen) { str('(') >> space? }
  rule(:rparen) { str(')') >> space? }
  rule(:comma)  { str(',') >> space? }
  rule(:dot)    { str('.') >> space? }
  rule(:plus)   { str('+') >> space? }
  rule(:minus)  { str('-') >> space? }
  rule(:star)   { str('*') >> space? }
  rule(:slash)  { str('/') >> space? }
  rule(:caret)  { str('^') >> space? }
  rule(:root)   { str('√') >> space? }

  rule(:identifier) { match('[a-zA-Z]').repeat(1) >> match('[a-zA-Z0-9_]').repeat }
  rule(:column_name) { identifier.as(:column_name) >> dot >> identifier.as(:table_name) >> lparen >>
                      match('[0-9]+').as(:start) >> comma >> match('[0-9]+').as(:end) >> rparen }
  rule(:number) { (match('[+-]').maybe >> digits >> str('.').maybe >> digits.maybe).as(:number) }
  rule(:factor) { (str('-').as(:neg).maybe >> (column_name | number | lparen >> expression >> rparen)).as(:factor) }
  rule(:exponentiation) { factor.as(:left) >> caret >> exponentiation.as(:right) |
                         factor.as(:left) >> root >> number.as(:root) |
                         factor }
  rule(:term) { exponentiation.as(:left) >> (star >> term.as(:right) | slash >> term.as(:right)).repeat }
  rule(:expression) { term.as(:left) >> (plus >> expression.as(:right) | minus >> expression.as(:right)).repeat }
