const { RTCPeerConnection } = require("wrtc");
const net = require("net");

const AUDIO_PORT = 12345;
const RTP_PORT = 5004;

// Create a TCP server to receive the raw audio data from FFmpeg
const server = net.createServer((socket) => {
  // Create an RTCPeerConnection to send RTP packets
  const pc = new RTCPeerConnection();

  // Add a raw audio track to the RTCPeerConnection
  const track = pc.addTransceiver("audio", {
