```typescript
async function fetchAndLogOpenInterest(symbols: string[], previousOpenInterests: Map<string, OpenInterestHistory[]>) {
  const currentTime = Date.now();

  for (const symbol of symbols) {
    const openInterest = await getOpenInterest(symbol);

    if (openInterest === null) {
      continue;
    }

    const history = previousOpenInterests.get(symbol) || [];
    history.push({ timestamp: currentTime, value: openInterest });

    // Remove entries older than 10 minutes
    while (history.length > 0 && currentTime - history[0].timestamp > 10 * 60 * 1000) {
      history.shift();
    }

    const intervals = [
      { minutes: 1, threshold: 0.5 },
      { minutes: 3, threshold: 1 },
      { minutes: 10, threshold: 2 },
    ];

    for (const { minutes, threshold } of intervals) {
      const pastTimestamp = currentTime - minutes * 60 * 1000;
      const pastIndex = history.findIndex((entry) => entry.timestamp >= pastTimestamp);

      if (pastIndex >= 0) {
        const pastValue = history[pastIndex].value;
        const percentageChange = ((openInterest - pastValue) / pastValue) * 100;

        if (Math.abs(percentageChange) > threshold) {
          console.log(
            `${symbol} Open Interest changed by ${percentageChange.toFixed(2)}% over ${minutes} minutes: ${pastValue} -> ${openInterest}`,
          );
        }
      }
    }

    previousOpenInterests.set(symbol, history);
  }
}
