// Returns the local gateway address using the getifaddrs function.
// The local gateway address is the destination address of the default
// network interface.
Address GetLocalGateway() {
  struct ifaddrs *ifap, *ifa;
  getifaddrs(&ifap);
  for (ifa = ifap; ifa; ifa = ifa->ifa_next) {
    // Find the default network interface.
    if (ifa->ifa_name && ifa->ifa_name[0] != 'l' && ifa->ifa_name[1] != 'o') {
      // Get the destination address of the default network interface.
      if (ifa->ifa_addr && ifa->ifa_addr->sa_family == AF_INET) {
        struct sockaddr_in *sa = (struct sockaddr_in *) ifa->ifa_dstaddr;
        char str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(sa->sin_addr), str, INET_ADDRSTRLEN);
        Address address;
        address.ipv4 = str;
        if (ifa->ifa_addr && ifa->ifa_addr->sa_family == AF_INET6) {
          struct sockaddr_in6 *sa = (struct sockaddr_in6 *) ifa->ifa_dstaddr;
          char str[INET6_ADDRSTRLEN];
          inet_ntop(AF_INET6, &(sa->sin6_addr), str, INET6_ADDRSTRLEN);
