type Message = { type: string, payload?: any }

type Actor = (message: Message) => Actor

type ExternalInterface = {
  send: (actorName: string, message: Message) => void,
  receive: (actorName: string, callback: (output: any) => void) => void
}

const counter: Actor = (state = 0) => (message) => {
  switch (message.type) {
    case 'increment':
      return counter(state + 1)
    case 'decrement':
      return counter(state - 1)
    case 'getCount':
      return counter({ ...state, output: state })
    default:
      return counter(state)
  }
}

const system = (actors: { [name: string]: Actor }) => {
  const receive = (name: string, message: Message) => {
    actors[name] = actors[name](message)
    if (actors[name].output) {
      const output = actors[name].output
      delete actors[name].output
      return output
    }
  }

  return { receive }
}

const actors = {
  counter: counter(0)
}

const { receive } = system(actors)

const externalInterface: ExternalInterface = {
  send: (actorName, message) => {
    receive(actorName, message)
  },
  receive: (actorName, callback) => {
    setInterval(() => {
      const output = receive(actorName, { type: 'getCount' })
      if (output !== undefined) {
        callback(output)
      }
    }, 1000)
  }
}

